STRUCT = {'group', 'controller', 'sampler'}

def applies_to(tree, sampler_name):
    def walk(node, inherited):
        own = [c['name'] for c in node.get('children', []) if c['kind'] not in STRUCT]
        if node['kind'] == 'sampler':
            return inherited + own if node['name'] == sampler_name else None
        here = inherited + own
        for c in node.get('children', []):
            if c['kind'] in STRUCT:
                r = walk(c, here)
                if r is not None:
                    return r
        return None
    return walk(tree, []) or []

